  "profile.loadError": { en: "Could not load your profile. Make sure the backend is reachable and your credentials are set up.", it: "Impossibile caricare il profilo. Verifica che il backend sia raggiungibile e le credenziali impostate.", es: "No se pudo cargar tu perfil. Asegúrate de que el backend sea accesible y las credenciales estén configuradas.", fr: "Impossible de charger votre profil. Vérifiez que le backend est joignable et vos identifiants configurés.", de: "Profil konnte nicht geladen werden. Stelle sicher, dass das Backend erreichbar ist und die Zugangsdaten gesetzt sind.", pt: "Não foi possível carregar o perfil. Confirma que o backend está acessível e as credenciais configuradas." },
  "metric.bmr": { en: "Basal Metabolic Rate", it: "Metabolismo basale", es: "Metabolismo basal", fr: "Métabolisme de base", de: "Grundumsatz", pt: "Metabolismo basal" },
  "metric.bmr.text": { en: "The calories your body burns at complete rest, just to keep vital functions going — breathing, circulation, brain activity. It's your baseline before any movement or exercise is added.", it: "Le calorie che il corpo brucia a riposo completo, solo per le funzioni vitali — respiro, circolazione, attività cerebrale. È la base prima di qualsiasi movimento o esercizio.", es: "Las calorías que tu cuerpo quema en reposo total, solo para las funciones vitales — respiración, circulación, actividad cerebral. Es tu base antes de cualquier movimiento o ejercicio.", fr: "Les calories brûlées au repos complet, juste pour les fonctions vitales — respiration, circulation, activité cérébrale. C'est votre base avant tout mouvement ou exercice.", de: "Die Kalorien, die dein Körper in völliger Ruhe verbrennt, nur für lebenswichtige Funktionen — Atmung, Kreislauf, Gehirn. Deine Basis vor jeder Bewegung.", pt: "As calorias que o corpo gasta em repouso total, só para funções vitais — respiração, circulação, atividade cerebral. É a tua base antes de qualquer movimento." },
  "metric.bmi": { en: "Body Mass Index", it: "Indice di massa corporea", es: "Índice de masa corporal", fr: "Indice de masse corporelle", de: "Body-Mass-Index", pt: "Índice de massa corporal" },
  "metric.bmi.text": { en: "Your weight relative to your height (kg/m²). It's a quick screening number for under-, normal- and over-weight ranges, but it doesn't tell muscle from fat, so treat it as a rough guide.", it: "Il tuo peso rispetto all'altezza (kg/m²). È un numero di screening rapido per sotto-, normo- e sovrappeso, ma non distingue muscolo da grasso: usalo come indicazione di massima.", es: "Tu peso en relación con tu altura (kg/m²). Es un número orientativo para bajo, normal y sobrepeso, pero no distingue músculo de grasa: tómalo como guía aproximada.", fr: "Votre poids rapporté à votre taille (kg/m²). Un repère rapide pour insuffisance, normalité et surpoids, mais il ne distingue pas le muscle du gras : à titre indicatif.", de: "Dein Gewicht im Verhältnis zur Größe (kg/m²). Ein schneller Richtwert für Unter-, Normal- und Übergewicht, unterscheidet aber nicht Muskel von Fett — nur grobe Orientierung.", pt: "O teu peso em relação à altura (kg/m²). É um número rápido para baixo, normal e excesso de peso, mas não distingue músculo de gordura: usa como guia." },
  "metric.water": { en: "Water requirement", it: "Fabbisogno idrico", es: "Necesidad de agua", fr: "Besoin en eau", de: "Wasserbedarf", pt: "Necessidade de água" },
  "metric.water.text": { en: "An estimate of the fluids your body needs each day, based mainly on your weight. It's a general guideline, not a strict target — your needs rise with heat, exercise and illness.", it: "Una stima dei liquidi di cui il corpo ha bisogno ogni giorno, basata soprattutto sul peso. È un'indicazione generale, non un obiettivo rigido — il fabbisogno cresce con caldo, esercizio e malattia.", es: "Una estimación de los líquidos que tu cuerpo necesita al día, basada sobre todo en tu peso. Es una guía general, no un objetivo estricto — sube con el calor, el ejercicio y la enfermedad.", fr: "Une estimation des liquides dont votre corps a besoin chaque jour, surtout selon votre poids. C'est un repère général, pas une cible stricte — il augmente avec la chaleur, l'effort et la maladie.", de: "Eine Schätzung der täglich benötigten Flüssigkeit, vor allem nach Gewicht. Ein allgemeiner Richtwert, kein striktes Ziel — der Bedarf steigt bei Hitze, Sport und Krankheit.", pt: "Uma estimativa dos líquidos que o corpo precisa por dia, sobretudo pelo peso. É um guia geral, não uma meta rígida — aumenta com calor, exercício e doença." },
  "metric.adaptiveTdee": { en: "Adaptive TDEE", it: "TDEE adattivo", es: "TDEE adaptativo", fr: "TDEE adaptatif", de: "Adaptiver TDEE", pt: "TDEE adaptativo" },
  "metric.logYourWeight": { en: "Log your weight", it: "Registra il peso", es: "Registra tu peso", fr: "Notez votre poids", de: "Gewicht eintragen", pt: "Regista o teu peso" },
