  // --- Open Food Facts (search) ---
  "off.title": { en: "Open Food Facts", it: "Open Food Facts", es: "Open Food Facts", fr: "Open Food Facts", de: "Open Food Facts", pt: "Open Food Facts" },
  "off.help": { en: "Open Food Facts is a free, community database of packaged foods. Search a product to import its nutrition into your foods.", it: "Open Food Facts è un database libero e collaborativo di alimenti confezionati. Cerca un prodotto per importarne i valori nei tuoi alimenti.", es: "Open Food Facts es una base de datos libre y comunitaria de alimentos envasados. Busca un producto para importar su nutrición a tus alimentos.", fr: "Open Food Facts est une base communautaire et gratuite d'aliments emballés. Cherchez un produit pour importer sa nutrition dans vos aliments.", de: "Open Food Facts ist eine freie, gemeinschaftliche Datenbank verpackter Lebensmittel. Suche ein Produkt, um seine Nährwerte zu importieren.", pt: "Open Food Facts é uma base de dados livre e comunitária de alimentos embalados. Procura um produto para importar a nutrição para os teus alimentos." },
  "off.searchPlaceholder": { en: "Search a product (e.g. black beans)", it: "Cerca un prodotto (es. fagioli neri)", es: "Busca un producto (p. ej. frijoles negros)", fr: "Cherchez un produit (ex. haricots noirs)", de: "Produkt suchen (z. B. schwarze Bohnen)", pt: "Procura um produto (ex. feijão preto)" },
  "off.search": { en: "Search", it: "Cerca", es: "Buscar", fr: "Rechercher", de: "Suchen", pt: "Procurar" },
  "off.orScan": { en: "or scan a barcode", it: "oppure scansiona un codice a barre", es: "o escanea un código de barras", fr: "ou scannez un code-barres", de: "oder Barcode scannen", pt: "ou lê um código de barras" },
  "off.searchFailed": { en: "Open Food Facts search failed. Try again shortly.", it: "Ricerca su Open Food Facts fallita. Riprova tra poco.", es: "La búsqueda en Open Food Facts falló. Inténtalo en breve.", fr: "Échec de la recherche Open Food Facts. Réessayez bientôt.", de: "Open-Food-Facts-Suche fehlgeschlagen. Versuch es gleich erneut.", pt: "A pesquisa no Open Food Facts falhou. Tenta daqui a pouco." },
  "off.noResults": { en: "No results.", it: "Nessun risultato.", es: "Sin resultados.", fr: "Aucun résultat.", de: "Keine Ergebnisse.", pt: "Sem resultados." },
  "off.typeTwo": { en: "Type at least 2 characters and press Search.", it: "Scrivi almeno 2 caratteri e premi Cerca.", es: "Escribe al menos 2 caracteres y pulsa Buscar.", fr: "Saisissez au moins 2 caractères et appuyez sur Rechercher.", de: "Mindestens 2 Zeichen eingeben und Suchen drücken.", pt: "Escreve pelo menos 2 caracteres e prime Procurar." },
  "off.import": { en: "Import", it: "Importa", es: "Importar", fr: "Importer", de: "Importieren", pt: "Importar" },
