  "barcode.permNeeded": { en: "Camera permission is needed to scan products.", it: "Serve il permesso fotocamera per scansionare i prodotti.", es: "Se necesita permiso de cámara para escanear productos.", fr: "L'autorisation caméra est nécessaire pour scanner les produits.", de: "Für das Scannen wird die Kamera-Berechtigung benötigt.", pt: "É necessária permissão da câmara para ler produtos." },
  "barcode.allowCamera": { en: "Allow camera", it: "Consenti fotocamera", es: "Permitir cámara", fr: "Autoriser la caméra", de: "Kamera erlauben", pt: "Permitir câmara" },
