  "barcode.lookupError": { en: "Network error during lookup. Try again.", it: "Errore di rete durante la ricerca. Riprova.", es: "Error de red durante la búsqueda. Inténtalo de nuevo.", fr: "Erreur réseau pendant la recherche. Réessayez.", de: "Netzwerkfehler bei der Suche. Versuch es erneut.", pt: "Erro de rede durante a procura. Tenta de novo." },
