  // --- Meals ---
  "meals.title": { en: "Meals", it: "Pasti", es: "Comidas", fr: "Repas", de: "Mahlzeiten", pt: "Refeições" },
  "meals.lead": { en: "Your meals organize the diary. Drag the handle on the left to reorder, tap a name to rename, or delete — deleting a meal keeps its past entries under \"Other\".", it: "I pasti organizzano il diario. Trascina la maniglia a sinistra per riordinare, tocca un nome per rinominarlo o eliminalo — eliminando un pasto le voci passate restano sotto \"Altro\".", es: "Tus comidas organizan el diario. Arrastra el asa de la izquierda para reordenar, toca un nombre para renombrar o elimínalo — al eliminar una comida sus entradas pasadas quedan en \"Otros\".", fr: "Vos repas organisent le journal. Glissez la poignée à gauche pour réordonner, touchez un nom pour le renommer ou supprimez — supprimer un repas conserve ses entrées passées sous « Autre ».", de: "Deine Mahlzeiten gliedern das Tagebuch. Ziehe links am Griff zum Sortieren, tippe einen Namen zum Umbenennen oder lösche — gelöschte Mahlzeiten behalten ihre alten Einträge unter „Sonstige\".", pt: "As tuas refeições organizam o diário. Arrasta a pega à esquerda para reordenar, toca num nome para renomear ou elimina — ao eliminar uma refeição as entradas antigas ficam em \"Outros\"." },
  "meals.loadError": { en: "Could not load meals. Check connection/credentials.", it: "Impossibile caricare i pasti. Controlla connessione/credenziali.", es: "No se pudieron cargar las comidas. Revisa conexión/credenciales.", fr: "Impossible de charger les repas. Vérifiez connexion/identifiants.", de: "Mahlzeiten konnten nicht geladen werden. Prüfe Verbindung/Zugangsdaten.", pt: "Não foi possível carregar as refeições. Verifica ligação/credenciais." },
  "meals.newName": { en: "New meal name", it: "Nome nuovo pasto", es: "Nombre de nueva comida", fr: "Nom du nouveau repas", de: "Name der neuen Mahlzeit", pt: "Nome da nova refeição" },
  "meals.deleteTitle": { en: "Delete meal", it: "Eliminare il pasto", es: "Eliminar comida", fr: "Supprimer le repas", de: "Mahlzeit löschen", pt: "Eliminar refeição" },
  "meals.deleteMsg": { en: "Delete \"{name}\"? Past entries will move to \"Other\".", it: "Eliminare \"{name}\"? Le voci passate andranno in \"Altro\".", es: "¿Eliminar \"{name}\"? Las entradas pasadas pasarán a \"Otros\".", fr: "Supprimer « {name} » ? Les entrées passées iront dans « Autre ».", de: "„{name}\" löschen? Alte Einträge wandern zu „Sonstige\".", pt: "Eliminar \"{name}\"? As entradas antigas vão para \"Outros\"." },

