  // --- Edit entry ---
  "editEntry.lead": { en: "Adjust the amount — the macros update with it.", it: "Regola la quantità — i macro si aggiornano di conseguenza.", es: "Ajusta la cantidad — los macros se actualizan con ella.", fr: "Ajustez la quantité — les macros suivent.", de: "Menge anpassen — die Makros passen sich an.", pt: "Ajusta a quantidade — os macros atualizam-se." },

  // --- Foods (resto) ---
  "foods.title": { en: "Foods", it: "Alimenti", es: "Alimentos", fr: "Aliments", de: "Lebensmittel", pt: "Alimentos" },
  "foods.lead": { en: "Your personal food library. Add the foods you eat so you can log them in seconds and the meal scanner can match them automatically. Tap a food below to edit it.", it: "La tua libreria personale di alimenti. Aggiungi i cibi che mangi per registrarli in pochi secondi e farli abbinare dallo scanner. Tocca un alimento qui sotto per modificarlo.", es: "Tu biblioteca personal de alimentos. Añade los que comes para registrarlos en segundos y que el escáner los reconozca. Toca un alimento abajo para editarlo.", fr: "Votre bibliothèque d'aliments. Ajoutez ce que vous mangez pour l'enregistrer en quelques secondes et permettre au scanner de le reconnaître. Touchez un aliment ci-dessous pour le modifier.", de: "Deine persönliche Lebensmittel-Bibliothek. Füge hinzu, was du isst, um es in Sekunden zu erfassen und vom Scanner erkennen zu lassen. Tippe unten ein Lebensmittel an, um es zu bearbeiten.", pt: "A tua biblioteca pessoal de alimentos. Adiciona o que comes para registar em segundos e o scanner reconhecer. Toca num alimento abaixo para o editar." },
  "foods.addFood": { en: "Add a food", it: "Aggiungi un alimento", es: "Añadir un alimento", fr: "Ajouter un aliment", de: "Lebensmittel hinzufügen", pt: "Adicionar um alimento" },
  "foods.yourFoods": { en: "Your foods", it: "I tuoi alimenti", es: "Tus alimentos", fr: "Vos aliments", de: "Deine Lebensmittel", pt: "Os teus alimentos" },
  "foods.none": { en: "No foods yet. Add your first one above.", it: "Ancora nessun alimento. Aggiungi il primo qui sopra.", es: "Aún no hay alimentos. Añade el primero arriba.", fr: "Aucun aliment. Ajoutez le premier ci-dessus.", de: "Noch keine Lebensmittel. Füge oben das erste hinzu.", pt: "Ainda sem alimentos. Adiciona o primeiro acima." },
  "foods.loadError": { en: "Could not load. Check backend/credentials.", it: "Caricamento non riuscito. Controlla backend/credenziali.", es: "No se pudo cargar. Revisa backend/credenciales.", fr: "Chargement impossible. Vérifiez backend/identifiants.", de: "Laden fehlgeschlagen. Prüfe Backend/Zugangsdaten.", pt: "Não foi possível carregar. Verifica backend/credenciais." },
  "foods.editFood": { en: "Edit food", it: "Modifica alimento", es: "Editar alimento", fr: "Modifier l'aliment", de: "Lebensmittel bearbeiten", pt: "Editar alimento" },
  "foods.newFood": { en: "New food", it: "Nuovo alimento", es: "Nuevo alimento", fr: "Nouvel aliment", de: "Neues Lebensmittel", pt: "Novo alimento" },
  "foods.optSearchTitle": { en: "Search the food database", it: "Cerca nel database alimenti", es: "Buscar en la base de alimentos", fr: "Chercher dans la base d'aliments", de: "Lebensmittel-Datenbank durchsuchen", pt: "Procurar na base de alimentos" },
  "foods.optSearchSub": { en: "Open Food Facts: a free, community-run database of packaged foods from around the world. Find a product and import its nutrition.", it: "Open Food Facts: un database libero e collaborativo di alimenti confezionati da tutto il mondo. Trova un prodotto e importane i valori.", es: "Open Food Facts: una base libre y comunitaria de alimentos envasados de todo el mundo. Encuentra un producto e importa su nutrición.", fr: "Open Food Facts : une base communautaire et gratuite d'aliments emballés du monde entier. Trouvez un produit et importez sa nutrition.", de: "Open Food Facts: eine freie, gemeinschaftliche Datenbank verpackter Lebensmittel weltweit. Produkt finden und Nährwerte importieren.", pt: "Open Food Facts: uma base livre e comunitária de alimentos embalados de todo o mundo. Encontra um produto e importa a nutrição." },
  "foods.optBarcodeTitle": { en: "Scan a barcode", it: "Scansiona un codice a barre", es: "Escanear un código de barras", fr: "Scanner un code-barres", de: "Barcode scannen", pt: "Ler um código de barras" },
  "foods.optBarcodeSub": { en: "Point the camera at a product's barcode to look it up and import it.", it: "Inquadra il codice a barre di un prodotto per cercarlo e importarlo.", es: "Apunta la cámara al código de barras de un producto para buscarlo e importarlo.", fr: "Visez le code-barres d'un produit pour le rechercher et l'importer.", de: "Richte die Kamera auf den Barcode eines Produkts, um es zu suchen und zu importieren.", pt: "Aponta a câmara ao código de barras de um produto para o procurar e importar." },
  "foods.optManualTitle": { en: "Enter manually", it: "Inserisci a mano", es: "Introducir manualmente", fr: "Saisir manuellement", de: "Manuell eingeben", pt: "Introduzir manualmente" },
  "foods.optManualSub": { en: "Type the name and the macros — per 100 g or for a portion you choose.", it: "Scrivi il nome e i macro — per 100 g o per una porzione che scegli.", es: "Escribe el nombre y los macros — por 100 g o por una porción que elijas.", fr: "Saisissez le nom et les macros — pour 100 g ou pour une portion de votre choix.", de: "Name und Makros eingeben – pro 100 g oder für eine gewählte Portion.", pt: "Escreve o nome e os macros — por 100 g ou para uma porção à escolha." },
  "foods.valuesAreFor": { en: "Values are for", it: "I valori sono per", es: "Los valores son para", fr: "Les valeurs sont pour", de: "Werte gelten für", pt: "Os valores são para" },
  "foods.per100": { en: "Per 100 g", it: "Per 100 g", es: "Por 100 g", fr: "Pour 100 g", de: "Pro 100 g", pt: "Por 100 g" },
  "foods.perPortion": { en: "Per portion", it: "Per porzione", es: "Por porción", fr: "Par portion", de: "Pro Portion", pt: "Por porção" },
  "foods.portionSize": { en: "Portion size", it: "Dimensione porzione", es: "Tamaño de porción", fr: "Taille de portion", de: "Portionsgröße", pt: "Tamanho da porção" },
  "foods.kcalManual": { en: "Calories set manually. Clear the field to compute them from the macros.", it: "Calorie inserite a mano. Svuota il campo per calcolarle dai macro.", es: "Calorías puestas a mano. Vacía el campo para calcularlas desde los macros.", fr: "Calories saisies à la main. Videz le champ pour les calculer depuis les macros.", de: "Kalorien manuell gesetzt. Feld leeren, um sie aus den Makros zu berechnen.", pt: "Calorias definidas à mão. Limpa o campo para as calcular a partir dos macros." },
  "foods.kcalAuto": { en: "Calories are computed from the macros (4/4/9). You can override them.", it: "Le calorie sono calcolate dai macro (4/4/9). Puoi sovrascriverle.", es: "Las calorías se calculan desde los macros (4/4/9). Puedes sobrescribirlas.", fr: "Les calories sont calculées depuis les macros (4/4/9). Vous pouvez les remplacer.", de: "Kalorien werden aus den Makros berechnet (4/4/9). Du kannst sie überschreiben.", pt: "As calorias são calculadas a partir dos macros (4/4/9). Podes substituí-las." },
  "foods.macrosPortionHint": { en: "Enter the macros for one portion of the size above; it's saved as the default portion.", it: "Inserisci i macro per una porzione della dimensione qui sopra; viene salvata come porzione predefinita.", es: "Introduce los macros para una porción del tamaño de arriba; se guarda como porción predeterminada.", fr: "Saisissez les macros pour une portion de la taille ci-dessus ; elle est enregistrée comme portion par défaut.", de: "Gib die Makros für eine Portion der obigen Größe ein; sie wird als Standardportion gespeichert.", pt: "Introduz os macros para uma porção do tamanho acima; é guardada como porção predefinida." },
  "foods.macrosPer100Hint": { en: "Enter the macros per 100 g.", it: "Inserisci i macro per 100 g.", es: "Introduce los macros por 100 g.", fr: "Saisissez les macros pour 100 g.", de: "Gib die Makros pro 100 g ein.", pt: "Introduz os macros por 100 g." },
