  "foods.couldNotSave": { en: "Could not save.", it: "Impossibile salvare.", es: "No se pudo guardar.", fr: "Enregistrement impossible.", de: "Speichern fehlgeschlagen.", pt: "Não foi possível guardar." },
  "foods.namePlaceholder": { en: "Name (e.g. Oats)", it: "Nome (es. Avena)", es: "Nombre (p. ej. Avena)", fr: "Nom (ex. Avoine)", de: "Name (z. B. Haferflocken)", pt: "Nome (ex. Aveia)" },
